def _normalize_format_args(formats, names, titles, aligned, byteorder):
    if formats is not None and not isinstance(formats, list):
        formats = list(formats) if hasattr(formats, '__iter__') and not isinstance(formats, str) else formats
    if names is not None and isinstance(names, str):
        names = names
    if titles is not None and isinstance(titles, str):
        titles = titles
    if aligned is None:
        aligned = False
    if byteorder is None:
        byteorder = None
    return formats, names, titles, aligned, byteorder


def _build_descr_from_format_args(formats, names, titles, aligned, byteorder):
